#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
size_t count_rectangles(const char*const*g,size_t rows){size_t count=0;for(size_t r=0;r<rows;r++)for(size_t c=0;c<strlen(g[r]);c++)if(g[r][c]=='+')for(size_t x=c+1;x<strlen(g[r]);x++){if(g[r][x]!='-'&&g[r][x]!='+')break;if(g[r][x]!='+')continue;for(size_t y=r+1;y<rows;y++){if(strlen(g[y])<=x)break;if((g[y][c]!='|'&&g[y][c]!='+')||(g[y][x]!='|'&&g[y][x]!='+'))break;if(g[y][c]=='+'&&g[y][x]=='+'){bool ok=true;for(size_t k=c+1;k<x;k++)if(g[y][k]!='-'&&g[y][k]!='+')ok=false;if(ok)count++;}}}return count;}

